t.script:
const hsIsShared = ;
const hsEmailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function hsToggleOptions(ev) {
    ev.stopPropagation();
    document.getElementById('hs-options').classList.toggle('open');
}
document.addEventListener('click', function () {
    const options = document.getElementById('hs-options');
    options && options.classList.remove('open');
});

function hsOpenModal(id) {
    document.getElementById('hs-options').classList.remove('open');
    document.getElementById(id).classList.add('show');
}
function hsCloseModal(id) {
    document.getElementById(id).classList.remove('show');
}

function hsCheckIdentity(nameId, emailId, errorId) {
    const name = document.getElementById(nameId).value.trim();
    const email = document.getElementById(emailId).value.trim();
    const error = document.getElementById(errorId);
    if (!name) {
        error.textContent = 'Please enter your name.';
        return null;
    }
    if (!hsEmailRe.test(email)) {
        error.textContent = 'Please enter a valid email address.';
        return null;
    }
    error.textContent = '';
    return { name: name, email: email };
}

function hsShowResult(title, message) {
    document.querySelectorAll('.hs-modal-overlay').forEach(el => el.classList.remove('show'));
    const actions = document.querySelector('#sign-topbar .actions');
    if (actions) actions.innerHTML = '';
    const body = document.getElementById('sign-body');
    if (body) {
        body.innerHTML = '';
        const result = document.createElement('div');
        result.className = 'hs-result w-100';
        const h2 = document.createElement('h2');
        h2.textContent = title;
        const p = document.createElement('p');
        p.textContent = message;
        result.append(h2, p);
        body.appendChild(result);
    }
}

async function hsDecline() {
    const error = document.getElementById('hs-decline-error');
    const reason = document.getElementById('hs-decline-reason').value.trim();
    const params = { access_token: accessToken || null, reason: reason };
    if (hsIsShared) {
        const identity = hsCheckIdentity('hs-decline-name', 'hs-decline-email', 'hs-decline-error');
        if (!identity) return;
        params.signer_name = identity.name;
        params.signer_email = identity.email;
    }
    if (!reason) {
        error.textContent = 'Please provide a reason for refusal.';
        return;
    }
    const button = document.getElementById('hs-decline-confirm');
    button.disabled = true;
    try {
        const response = await fetch('/hudson_sign/decline/' + reqId, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: params }),
        });
        const data = await response.json();
        const result = data.result || {};
        if (data.error || result.error) {
            error.textContent = result.error || (data.error.data && data.error.data.message) || 'An error occurred. Please try again.';
            return;
        }
        hsShowResult('You have declined to sign this document.', 'The sender has been notified. You can close this page.');
    } catch (e) {
        error.textContent = 'An error occurred. Please try again.';
    } finally {
        button.disabled = false;
    }
}

// Share link: the visitor tells who they are before the document is signed.
// The identity is kept in the visitor's session, so the page's own
// "Complete & Sign" request needs no change.
let hsIdentityConfirmed = false;
function hsResolveSigner() {
    hsCloseModal('hs-signer-overlay');
}
async function hsConfirmSigner() {
    const identity = hsCheckIdentity('hs-signer-name', 'hs-signer-email', 'hs-signer-error');
    if (!identity) return;
    const error = document.getElementById('hs-signer-error');
    try {
        const response = await fetch('/hudson_sign/identify/' + reqId, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {
                access_token: accessToken || null,
                signer_name: identity.name,
                signer_email: identity.email,
            } }),
        });
        const data = await response.json();
        const result = data.result || {};
        if (data.error || result.error) {
            error.textContent = result.error || (data.error.data && data.error.data.message) || 'An error occurred. Please try again.';
            return;
        }
    } catch (e) {
        error.textContent = 'An error occurred. Please try again.';
        return;
    }
    hsIdentityConfirmed = true;
    hsCloseModal('hs-signer-overlay');
    document.getElementById('btn-complete').click();
}
// Extra authentication "By Email": a one-time code sent to the signer
const hsOtpRequired = ;
let hsOtpVerified = false;
async function hsCall(url, params) {
    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: Object.assign({ access_token: accessToken || null }, params) }),
        });
        const data = await response.json();
        if (data.error) {
            return { error: (data.error.data && data.error.data.message) || 'An error occurred. Please try again.' };
        }
        return data.result || {};
    } catch (e) {
        return { error: 'An error occurred. Please try again.' };
    }
}
function hsOtpPassed() {
    hsOtpVerified = true;
    hsCloseModal('hs-otp-overlay');
    document.getElementById('btn-complete').click();
}
async function hsSendOtp() {
    const error = document.getElementById('hs-otp-error');
    const info = document.getElementById('hs-otp-info');
    error.textContent = '';
    info.textContent = 'Sending a verification code…';
    const result = await hsCall('/hudson_sign/otp/send/' + reqId, {});
    if (result.verified) {
        hsOtpPassed();
        return;
    }
    if (result.error) {
        info.textContent = '';
        error.textContent = result.error;
        return;
    }
    info.textContent = 'We sent a 6-digit code to ' + result.email + '. Enter it below to sign the document.';
    document.getElementById('hs-otp-code').focus();
}
async function hsVerifyOtp() {
    const error = document.getElementById('hs-otp-error');
    const code = document.getElementById('hs-otp-code').value.replace(/\s/g, '');
    if (!/^\d{6}$/.test(code)) {
        error.textContent = 'Please enter the 6-digit code.';
        return;
    }
    const button = document.getElementById('hs-otp-confirm');
    button.disabled = true;
    const result = await hsCall('/hudson_sign/otp/verify/' + reqId, { code: code });
    button.disabled = false;
    if (result.error) {
        error.textContent = result.error;
        return;
    }
    hsOtpPassed();
}
function hsOpenOtp() {
    document.getElementById('hs-otp-code').value = '';
    document.getElementById('hs-otp-overlay').classList.add('show');
    hsSendOtp();
}

// Before the page's own "Complete & Sign" handler (capture phase):
// who is signing (share link), then the email code
document.addEventListener('click', function (ev) {
    const button = ev.target.closest && ev.target.closest('#btn-complete');
    if (!button || button.disabled) return;
    const needIdentity = hsIsShared && !hsIdentityConfirmed;
    const needOtp = hsOtpRequired && !hsOtpVerified;
    if (!needIdentity && !needOtp) return;
    const progress = (document.getElementById('progress-label') || {}).textContent || '';
    const counts = progress.match(/(\d+)\s*\/\s*(\d+)/);
    if (counts && Number(counts[1]) < Number(counts[2])) {
        return;  // the page itself points to the fields left
    }
    ev.stopImmediatePropagation();
    ev.preventDefault();
    if (needIdentity) {
        document.getElementById('hs-signer-error').textContent = '';
        document.getElementById('hs-signer-overlay').classList.add('show');
        document.getElementById('hs-signer-name').focus();
    } else {
        hsOpenOtp();
    }
}, true);

// Once signed: "It's signed!" with the download, instead of leaving the page at once
let hsRedirectUrl = null;
function hsCloseSigned() {
    hsCloseModal('hs-signed-overlay');
    if (hsRedirectUrl) {
        window.location.replace(hsRedirectUrl);
    }
}
const hsFetch = window.fetch.bind(window);
window.fetch = async function (resource, options) {
    const response = await hsFetch(resource, options);
    const url = typeof resource === 'string' ? resource : (resource && resource.url) || '';
    if (!/\/my\/dms\/signature\/\d+\/accept/.test(url)) {
        return response;
    }
    let result;
    try {
        result = (await response.clone().json()).result;
    } catch (e) {
        return response;
    }
    if (!result || result.error) {
        return response;
    }
    if (result.next_signer_url) {
        const actions = document.querySelector('#sign-topbar .actions');
        if (actions) actions.innerHTML = '✓ Signed Successfully';
        document.getElementById('hs-next-name').textContent = result.next_signer_name || '';
        document.getElementById('hs-next-btn-name').textContent = result.next_signer_name || '';
        document.getElementById('hs-next-link').href = result.next_signer_url;
        document.getElementById('hs-next-overlay').classList.add('show');
        return new Promise(() => {});
    }
    hsRedirectUrl = result.redirect_url || null;
    const actions = document.querySelector('#sign-topbar .actions');
    if (actions) actions.innerHTML = '✓ Signed Successfully';
    const progress = document.getElementById('progress-bar');
    if (progress) progress.style.width = '100%';
    document.getElementById('hs-signed-text').textContent = result.hs_all_signed
        ? 'You will get the signed document by email.'
        : 'You will get the signed document by email once everyone has signed.';
    const download = document.getElementById('hs-signed-download');
    if (result.hs_download_url) {
        download.href = result.hs_download_url;
        download.style.display = '';
    } else {
        download.style.display = 'none';
    }
    document.getElementById('hs-signed-overlay').classList.add('show');
    // The page's own handler would leave the page: it never gets this answer
    return new Promise(() => {});
};
